// значение — контур (d) или готовая разметка внутри <svg> (начинается с «<»: поворот, несколько частей)
export const ico = (n, cls = '') => { const v = ICON[n] || ''; return `<svg class="ic${cls ? ' ' + cls : ''}" viewBox="0 0 512 512" aria-hidden="true">${v[0] === '<' ? v : `<path fill="currentColor" d="${v}"/>`}</svg>`; };
import { tr } from './i18n.js?v=20261029a';
// что сбивает комплекс (Mark 2026-10-25): значки после названия везде, где он показан. Правила — как в бою (sim/strike.js targetsFor, inEnv),
// они разные по режиму (ревью 2026-10-25): mode 'def' — оборона от налёта: бомбы и ракеты с самолётов, в том числе крылатые, берёт только
// antiMun; 'multi' — «Мульти-волна»: дроны, крылатые и планирующие бомбы волны — любой с РЛС, ИК-ГСН или пушками, если нижняя граница зоны
// ниже их высоты (дроны — от 120 м, крылатые — 30–70 м: нужна граница ниже 60 м); баллистику везде — только abm (вероятность за перехват —
// как в бою: abm × 1,5, не больше 90 %). Без mode (Арсенал, Справка, исследования) — всё, подсказка называет режим
export function samCaps(S, mode = '') {
  if (!S) return [];
  const sees = !!(S.radar || S.type === 'ir' || S.type === 'guns'), mw = mode !== 'def', df = mode !== 'multi', out = [];
  if (mw && sees && S.hmin < 120) out.push({ k: 'drone', ic: 'capDrone', t: tr('Сбивает дроны «Мульти-волны»') });
  if (df && S.antiMun) out.push({ k: 'bomb', ic: 'capBomb', t: tr('Сбивает бомбы и ракеты с самолётов, в том числе крылатые') });
  if (mw && sees && S.hmin < 60) out.push({ k: 'cruise', ic: 'capCruise', t: tr('Сбивает крылатые ракеты «Мульти-волны» (ниже {0} м — нет)', [S.hmin]) });
  if (S.abm) out.push({ k: 'tbm', ic: 'capTbm', t: tr('Сбивает баллистические ракеты: перехват {0} %', [Math.round(Math.min(0.9, S.abm * 1.5) * 100)]) });
  return out;
}
export const capsHtml = (S, mode = '', cls = '') => { const c = samCaps(S, mode); return c.length ? `<span class="caps${cls ? ' ' + cls : ''}">${c.map((q) => `<span class="${q.k}" title="${q.t}">${ico(q.ic)}</span>`).join('')}</span>` : ''; };
// фильтр целей комплекса (Mark 2026-10-25: «либо все цели, либо только какие-то конкретные»): виды — как в sim/strike.js tgtCat. Переключается то,
// что комплекс в этом режиме может сбить: самолёты (оборона от налёта; в «Мульти-волне» носители вне района не цель) + плашки samCaps. Меньше двух видов — выбирать нечего
const tgtName = (k) => ({ air: tr('самолёты'), drone: tr('дроны'), bomb: tr('бомбы'), cruise: tr('крылатые'), tbm: tr('баллистика') })[k];
export function tgtChoices(S, mode = '') {
  const out = mode !== 'multi' ? [{ k: 'air', ic: '', t: tr('Самолёты и вертолёты налёта') }] : [];
  for (const c of samCaps(S, mode)) out.push({ k: c.k, ic: c.ic, t: c.t });
  return out.length > 1 ? out : [];
}
export const tgtOn = (u, k) => !u.tgt || u.tgt.has(k);
// строка «цели: все» / «цели: дроны, бомбы» для сводки карточки ('' — выбирать нечего)
export function tgtLabel(u, mode = '') {
  const ch = tgtChoices(u.S, mode); if (!ch.length) return '';
  const on = ch.filter((q) => tgtOn(u, q.k));
  return tr('цели: {0}', [!u.tgt || on.length === ch.length ? tr('все') : on.map((q) => tgtName(q.k)).join(', ')]);
}
// строка кнопок в карточке комплекса: «Все» и плашки видов (цвета — как у плашек «что сбивает», самолёты — нейтральный)
export function tgtRowHtml(u, mode = '') {
  const ch = tgtChoices(u.S, mode); if (!ch.length) return '';
  const all = !u.tgt || ch.every((q) => tgtOn(u, q.k));
  return `<div class="tgtrow"><span class="tl">${tr('Цели')}</span><button class="tg all${all ? ' on' : ''}" data-a="tgall">${tr('Все')}</button>${ch.map((q) => `<button class="tg ${q.k}${tgtOn(u, q.k) ? ' on' : ''}" data-a="tg" data-k="${q.k}" title="${q.t}">${q.ic ? ico(q.ic) : ''}${tgtName(q.k)}</button>`).join('')}</div>`;
}
// упоминание кнопки в тексте (обучение, руководство, пауза, подсказки) — со значком: «Ловушки» → [значок] «Ловушки»
const TOK = { '«Ловушки»': 'flares', '«Карта»': 'map', '«Цель»': 'target', '«Авто»': 'auto', '«Газ»': 'throttle', '«Обзор»': 'camera', '«Кам.»': 'camera', '«Пуск»': 'fire', '«Огонь»': 'fire',
  '«Бинокль»': 'bino', '«РЛС»': 'radar', '«?»': 'lesson', '«Игроки»': 'players', '«Помощь»': 'help', '⛽': 'fuel', '👥': 'players', '«Время ×4»': 'speed',
  '«◎»': '', '"◎"': '', '“◎”': '', '▲▼': 'triU+triD', '◀▶': 'triL+tri', '▲': 'triU', '▼': 'triD', '◀': 'triL', '▶': 'tri', '✓': 'ok', '✕': 'close', '☰': 'list', '⚙': 'cog', '⚠': 'hazard', '➤': 'send', '🔑': 'key', '★': 'star',
  '↻': 'rotCw', '⟳': 'rotCw', '⟲': 'rotCcw', '◎': 'hideUi', // «◎» в кавычках — строка цели контейнера в панели, не значок; ◎ без кавычек — «спрятать интерфейс»
}; // эмодзи и символы — заменяются значком целиком
// точки статуса: рисуются CSS (.sd в airdef.html), цвет — как у текста
const DOT = { '●': 'sd', '○': 'sd o', '◆': 'sd d' };
// те же кнопки в английском тексте — в «…» и в "…" (переводчики пишут по-разному): "Countermeasures", "Map", "Target", "Auto", "Throttle", "View", "Cam.", "Fire" / "Launch", "Binoculars", "Radar", "Help", "Players"
for (const [icon, names] of Object.entries({ flares: ['Flares', 'Countermeasures', 'CMs'], map: ['Map'], target: ['Target'], auto: ['Auto'], throttle: ['Throttle'], camera: ['View', 'Look', 'Cam.', 'Camera'], fire: ['Fire', 'Launch'], bino: ['Binos', 'Binoculars'], radar: ['Radar'], help: ['Help'], players: ['Players'], lesson: ['?'] }))
  for (const n of names) { TOK['«' + n + '»'] = icon; TOK['"' + n + '"'] = icon; }
const TRE = new RegExp([...Object.keys(TOK), ...Object.keys(DOT)].map((k) => k.replace(/[.?]/g, '\\$&')).join('|'), 'g');
export const iconize = (h) => String(h ?? '').replace(TRE, (m) => {
  if (DOT[m]) return `<i class="${DOT[m]}"></i>`;
  if (TOK[m] === '') return m;
  return `<span class="bi">${TOK[m].split('+').map((n) => ico(n, 'ii')).join('')}${/^[«"]/.test(m) ? m : ''}</span>`;
});
// значок на canvas (подписи целей и т. п.): контур game-icons в квадрате size с центром (cx, cy); в Deno (без Path2D) — пропуск
export function drawIco(c, n, cx, cy, size) {
  const v = ICON[n]; if (!v || v[0] === '<' || typeof Path2D === 'undefined') return;
  c.save(); c.translate(cx - size / 2, cy - size / 2); c.scale(size / 512, size / 512); c.fill(new Path2D(v)); c.restore();
}
// легенда значков — для руководства
